from pathlib import Path
import base64

HUMAN_LIGHT = base64.b64decode('')
METAL_LIGHT = base64.b64decode('')
DRAW = base64.b64decode('ICBmbG9hdCBzcUwgPSAocXVpZXRNb2RlIHx8IGNydFN0YXRlID09IDIpID8gMC4wZiA6IGxpZ2h0U3F1aW50TDsKICBmbG9hdCBzcVIgPSAocXVpZXRNb2RlIHx8IGNydFN0YXRlID09IDIpID8gMC4wZiA6IGxpZ2h0U3F1aW50UjsKCiAgb0wgKj0gKDEuMGYgLSAwLjgwZiAqIHNxTCk7CiAgb1IgKj0gKDEuMGYgLSAwLjgwZiAqIHNxUik7CgoK')
SERIAL = base64.b64decode('')

TARGETS = {
    Path('eyes/KoraHumanMetalV18_S3_PUBLIC/KoraHumanMetalV18_S3_PUBLIC.ino'): HUMAN_LIGHT,
    Path('eyes/KoraMetalEyesV18_S3_PUBLIC/KoraMetalEyesV18_S3_PUBLIC.ino'): METAL_LIGHT,
    Path('eyes/KoraMonsterEyesV18_S3_PUBLIC/KoraMonsterEyesV18_S3_PUBLIC.ino'): METAL_LIGHT,
}


def replace_slice(data, start_anchor, end_anchor, replacement, label, include_end_line=False):
    try:
        start = data.index(start_anchor)
        end = data.index(end_anchor, start)
    except ValueError as exc:
        raise SystemExit(f'missing {label} anchor') from exc
    if include_end_line:
        nl = data.find(b'\n', end)
        if nl < 0:
            end = len(data)
        else:
            end = nl + 1
    return data[:start] + replacement + data[end:]


for path, light in TARGETS.items():
    data = path.read_bytes()
    data = replace_slice(data, b'// Ambient-light sensors:', b'static bool handleIrisPupil', light, f'{path} light')
    data = replace_slice(data, b'  float sqL = ', b'  oL *= displayPower.lid;', DRAW, f'{path} draw')
    data = replace_slice(
        data,
        b'  if (upper == "LIST") { printBehaviorList(); return; }',
        b'  triggerEarPerk();',
        SERIAL,
        f'{path} serial',
        include_end_line=True,
    )
    path.write_bytes(data)

for rej in Path('eyes').rglob('*.rej'):
    rej.unlink()
